//! WP-B1 corpus replay (docs/dev/builtin-corpus.md) for the suites generated by tests/language/gen/gen-b1.mjs. Every case
//! is re-executed through the runtime and compared with the V8 result. A suite must replay with zero failures and zero
//! missing targets.
//!
//! Replay-only realm setup: the corpus names Function.prototype members by path from the global object, and the kernel
//! deliberately has no Function global. `replay_realm` adds a holder named `Function` whose only property is `prototype`
//! (%FunctionPrototype%). It exists only in the replay realm; the product realm (Rt::new) has no Function global.

use vn_testkit::{replay_suite, ReplayOptions, ReplayReport};
use vn_value::{Flags, Intrinsic, PropKey, Rt, Value};

fn replay_realm(rt: &Rt) {
    let holder = rt.new_object();
    let fp = Value::Object(rt.intrinsic(Intrinsic::FunctionPrototype));
    assert!(rt.define_data(holder, PropKey::from_str("prototype"), fp, Flags::NONE).is_ok(), "replay holder");
    rt.install_global("Function", Value::Object(holder));
}

fn replay(text: &str) -> ReplayReport {
    let opts = ReplayOptions { setup: Some(replay_realm), ..Default::default() };
    let report = replay_suite(text, &opts);
    for f in &report.failures {
        eprintln!("{}: FAIL {}: {} (expected {}, actual {})", report.suite, f.id, f.reason, f.expected, f.actual);
    }
    for m in &report.missing {
        eprintln!("{}: MISSING {} ({})", report.suite, m.id, m.target);
    }
    eprintln!(
        "{}: {} passed of {}, {} failed, {} missing",
        report.suite,
        report.passed,
        report.total,
        report.failures.len(),
        report.missing.len()
    );
    report
}

fn assert_clean(report: &ReplayReport) {
    assert!(report.total > 0, "{}: the suite has no cases", report.suite);
    assert!(report.missing.is_empty(), "{}: {} missing targets", report.suite, report.missing.len());
    assert!(report.failures.is_empty(), "{}: {} failing cases", report.suite, report.failures.len());
}

#[test]
fn object_proto_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/object-proto.json")));
}

#[test]
fn object_own_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/object-own.json")));
}

#[test]
fn function_proto_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/function-proto.json")));
}

#[test]
fn symbol_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/symbol.json")));
}

#[test]
fn boolean_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/boolean.json")));
}

#[test]
fn globals_suite_replays_clean() {
    assert_clean(&replay(include_str!("../../../tests/language/builtins/globals.json")));
}
